'Customers_without_login_alert' => 'Àwọn wọ̀nyí ni àwọn oníbàárà POS / tí wọ́n ń wọlé tààrà tí wọn kò tíì ní àkáǹtì lórí ilé ìtajà orí ayélujára. Lo "Forúkọ Àkáǹtì Sílẹ̀" láti ṣẹ̀dá ìwọlé ilé ìtajà (ìmeèlì + ọ̀rọ̀ ìgbaniwọlé) kí oníbàárà lè wọlé kí ó sì ra ọjà lórí ilé ìtajà rẹ.',
