'Units_Guide_Title' => 'Bí àwọn ìwọ̀n ṣe ń ṣiṣẹ́',
'Units_Guide_Base' => 'Ìwọ̀n ìpìlẹ̀: fi "Ìwọ̀n Ìpìlẹ̀" sílẹ̀ ní òfìfo. A ń ka ọjà nígbà gbogbo pẹ̀lú ìwọ̀n yìí, bí àpẹẹrẹ Ẹyọ.',
'Units_Guide_Sub' => 'Ìwọ̀n kékeré: yan "Ìwọ̀n Ìpìlẹ̀" kan, lẹ́yìn náà lo "Àmì Ìṣiṣẹ́" àti "Iye Ìṣiṣẹ́" láti yí i padà sí ìwọ̀n ìpìlẹ̀ yẹn.',
'Units_Guide_Example_Multiply' => 'Àpẹẹrẹ: Àpótí kan tí ìwọ̀n ìpìlẹ̀ rẹ̀ jẹ́ Ẹyọ, àmì ìṣiṣẹ́ * àti iye 12. Títa Àpótí 1 yóò mú Ẹyọ 12 kúrò nínú ọjà.',
'Units_Guide_Example_Divide' => 'Àpẹẹrẹ: Gírámù kan tí ìwọ̀n ìpìlẹ̀ rẹ̀ jẹ́ Kílógírámù, àmì ìṣiṣẹ́ / àti iye 1000. Títa Gírámù 500 yóò mú Kílógírámù 0.5 kúrò nínú ọjà.',
'Units_Guide_Note' => 'Àwọn ìwọ̀n ìpìlẹ̀ nìkan ni a lè yàn gẹ́gẹ́ bí "Ìwọ̀n Ìpìlẹ̀", a kò sì lè pa ìwọ̀n kan rẹ́ nígbà tí àwọn ìwọ̀n kékeré ṣì ń lò ó.',

'Amount_Paid' => 'Iye Tí A San',
