'Show_Discount_Desc' => 'Ìdínkù owó tí a fi kan gbogbo ìtajà (pẹ̀lú ìdínkù àmì-ẹ̀san), tí a ń tẹ̀ jáde gẹ́gẹ́ bí ìlà tirẹ̀ nínú àpapọ̀.',
